-- Third Data source URLs (career-ops tracked_companies) + Tools/Data nav.
-- Apply on jobs (`RUN_MIGRATIONS_ON_BOOT=false`). Do not run on phpyun.

CREATE TABLE IF NOT EXISTS `phpyun_rs_third_data` (
    `id`         BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `name`       VARCHAR(200)    NOT NULL DEFAULT '',
    `url`        VARCHAR(512)    NOT NULL,
    `api_url`    VARCHAR(512)    NOT NULL DEFAULT '',
    `provider`   VARCHAR(32)     NOT NULL DEFAULT 'other',
    `sort`       INT              NOT NULL DEFAULT 0,
    `enabled`    TINYINT         NOT NULL DEFAULT 1,
    `created_at` INT UNSIGNED     NOT NULL DEFAULT 0,
    `updated_at` INT UNSIGNED     NOT NULL DEFAULT 0,
    PRIMARY KEY (`id`),
    UNIQUE KEY `uk_url` (`url`),
    KEY `ix_enabled_sort` (`enabled`, `sort`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;


SELECT 1064, '第三方数据', 123, 'index.php?m=tool&c=thirdData', 1, '0', 5, 0, 1, 3, '/thirdData'
FROM DUAL
WHERE NOT EXISTS (
    SELECT 1 FROM `phpyun_admin_navigation` WHERE `id` = 1064 OR `path` = '/thirdData'
);

